import { createStyleContext } from "@styled-system/jsx"
import { Slider as SliderPrimitive } from "radix-ui"

import { recipe } from "./recipe"

const { withContext, withProvider } = createStyleContext(recipe)

export const Root = withProvider(SliderPrimitive.Root, "root")

export const Track = withContext(SliderPrimitive.Track, "track")

export const Range = withContext(SliderPrimitive.Range, "range")

export const Thumb = withContext(SliderPrimitive.Thumb, "thumb")

import { sva } from "@styled-system/css"

export const recipe = sva({
  slots: ["root", "track", "range", "thumb"],
  base: {
    root: {
      position: "relative",
      display: "flex",
      touchAction: "none",
      userSelect: "none",
      alignItems: "center",
    },
    track: {
      position: "relative",
      h: "2",
      w: "full",
      flexGrow: "1",
      overflow: "hidden",
      rounded: "full",
      bg: "neutral",
    },
    range: {
      position: "absolute",
      h: "full",
      bg: "primary",
    },
    thumb: {
      display: "block",
      h: "5",
      w: "5",
      cursor: "pointer",
      rounded: "full",
      borderWidth: "2",
      borderColor: "stroke.ring",
      bg: "neutral",

      _disabled: {
        pointerEvents: "none",
        opacity: "0.5",
      },
    },
  },
})

import { cn } from "@utils/cn"
import { Slider as SliderPrimitive } from "radix-ui"
import {
  type ComponentPropsWithoutRef,
  type ElementRef,
  forwardRef,
} from "react"

import { slider } from "./styles"

const styles = slider()

export const Root = forwardRef<
  ElementRef<typeof SliderPrimitive.Root>,
  ComponentPropsWithoutRef<typeof SliderPrimitive.Root>
>(({ className, ...props }, ref) => (
  <SliderPrimitive.Root
    ref={ref}
    className={cn(styles.root(), className)}
    {...props}
  />
))

Root.displayName = SliderPrimitive.Root.displayName

export const Track = forwardRef<
  ElementRef<typeof SliderPrimitive.Track>,
  ComponentPropsWithoutRef<typeof SliderPrimitive.Track>
>(({ className, ...props }, ref) => (
  <SliderPrimitive.Track
    ref={ref}
    className={cn(styles.track(), className)}
    {...props}
  />
))

Track.displayName = SliderPrimitive.Track.displayName

export const Range = forwardRef<
  ElementRef<typeof SliderPrimitive.Range>,
  ComponentPropsWithoutRef<typeof SliderPrimitive.Range>
>(({ className, ...props }, ref) => (
  <SliderPrimitive.Range
    ref={ref}
    className={cn(styles.range(), className)}
    {...props}
  />
))

Range.displayName = SliderPrimitive.Range.displayName

export const Thumb = forwardRef<
  ElementRef<typeof SliderPrimitive.Thumb>,
  ComponentPropsWithoutRef<typeof SliderPrimitive.Thumb>
>(({ className, ...props }, ref) => (
  <SliderPrimitive.Thumb
    ref={ref}
    className={cn(styles.thumb(), className)}
    {...props}
  />
))

Thumb.displayName = SliderPrimitive.Thumb.displayName

import { tv } from "tailwind-variants"

export const slider = tv({
  slots: {
    root: "relative flex touch-none select-none items-center",
    track: "relative h-2 w-full grow overflow-hidden rounded-full bg-neutral",
    range: "absolute h-full bg-primary",
    thumb:
      "block size-5 cursor-pointer rounded-full border-2 border-stroke-ring bg-neutral disabled:pointer-events-none disabled:opacity-50",
  },
})
